import{_ as r,l as i,o as e,c as p,v as t,p as h,x as o,d as n,i as s,S as d}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"逆向选择与柠檬市场","description":"","frontmatter":{"title":"逆向选择与柠檬市场","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/akerlof-lemons.md","filePath":"econ/akerlof-lemons.md","lastUpdated":1789023840000}'),E={name:"econ/akerlof-lemons.md"};function c(m,a,f,B,_,u){const l=i("Mermaid");return e(),p("div",null,[a[1]||(a[1]=t('<h1 id="逆向选择与柠檬市场" tabindex="-1">逆向选择与柠檬市场 <a class="header-anchor" href="#逆向选择与柠檬市场" aria-label="Permalink to &quot;逆向选择与柠檬市场&quot;">​</a></h1><div class="epigraph"><p>卖方知道车的质量，买方只看见市场上的平均质量；价格下降驱逐好车，市场可以收缩到柠檬。</p><footer>—— Akerlof, The Market for “Lemons”: Quality Uncertainty and the Market Mechanism, QJE, 1970</footer></div><p><a href="/econ/school-choice">上一课</a>（学校选择）。给了隐藏类型下的信念与序贯理性。缺口是把类型读成商品质量，把「信号」先取最瘦的一种：价格本身。卖方知情、买方不知情，又没有教育、担保、菜单去分离，只剩一个公开市价。Akerlof 证明：这个市价会通过逆向选择把好车逐出，第一定理的商品空间再次列不全——列不全的是质量。本课钉柠檬，不写发送者先动的信号。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>质量 \\(\\theta\\) 是卖方类型，分布 \\(F\\) 为共同先验。卖方保留效用随 \\(\\theta\\) 升，买方对 \\(\\theta\\) 的评价也升，且买方评价高于卖方（否则无贸易增益）。买方只看见是否成交与价格，看不见 \\(\\theta\\)。给定价格 \\(p\\)，愿意出售的是 \\(\\theta\\le\\hat\\theta(p)\\) 的车，市场上的条件期望质量 \\(\\mu(p)=\\mathbb{E}[\\theta\\mid\\theta\\le\\hat\\theta(p)]\\) 随 \\(p\\) 下降而变差。</p><p>买方最多愿付 \\(\\mu(p)\\) 对应的评价。若该评价低于 \\(p\\)，这个价格出不清。可能没有任何 \\(p\\) 使「愿意买平均质量」与「该价格下愿意卖的集合」一致，互利交易全部消失。即使有均衡价格，好车仍可能卖不掉。这是逆向选择：参与决策本身携带类型信息，把条件分布朝坏的方向推。</p><h3 id="逆向选择不是道德风险" tabindex="-1">逆向选择不是道德风险 <a class="header-anchor" href="#逆向选择不是道德风险" aria-label="Permalink to &quot;逆向选择不是道德风险&quot;">​</a></h3><p>这里行动（卖或不卖）在质量已实现之后，质量是隐藏类型，不是隐藏努力。隐藏行动是后课。柠檬里即使人人诚实报质量，只要质量不可验证、不可写入合同，问题仍在——缺的是可签约的商品维。</p><p><span class="marginnote">Akerlof 的数字教具：质量均匀分布，卖方评价等于质量，买方评价是质量的倍数。需求取决于平均质量，供给取决于价格切断点，两者可以不相交。附录课读 1970 原文；本课只把机制接入 PBE：卖方策略是类型依存的出售阈值。</span></p><p>好车的卖方保留效用高，给定 \\(p\\) 更不卖。 切断从下往上吃供给，条件期望质量被拉低，这是逆向选择的会计，不是偏好变坏。 互利交易可以全部消失，即使买方对每辆车的评价都高于卖方。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把市场写成买方竞争（或一个代表性买方）加卖方类型连续统。均衡价格使需求等于该价格下的供给，且买方信念等于该供给集上的条件期望——路径上的贝叶斯。若只有一个价格、没有其他信号，分离做不到：不同 \\(\\theta\\) 要么都卖、要么按阈值切断，是混同或半混同。</p><p>担保、品牌、强制检验是把质量重新变成可签约商品，或变成下一课的昂贵信号。本课先让市场只靠价格，才能看见失灵有多干净。</p>',13)),(e(),h(d,null,{default:o(()=>[s(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20TYPE%5B%22%E5%8D%96%E6%96%B9%E7%A7%81%E7%9F%A5%20%CE%B8%22%5D%20--%3E%20P%5B%22%E5%85%AC%E5%BC%80%E4%BB%B7%E6%A0%BC%20p%22%5D%0A%20%20P%20--%3E%20SEL%5B%22%E4%BD%8E%20%CE%B8%20%E6%9B%B4%E6%84%BF%E6%84%8F%E5%8D%96%22%5D%0A%20%20SEL%20--%3E%20MU%5B%22%CE%BC%20%3D%20E%5B%CE%B8%20%7C%20%E5%87%BA%E5%94%AE%5D%22%5D%0A%20%20MU%20--%3E%20UNRAVEL%5B%22%E5%A5%BD%E8%BD%A6%E9%80%80%E5%87%BA%EF%BC%8C%E5%B8%82%E5%9C%BA%E8%90%8E%E7%BC%A9%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>价格有两个角色：支付手段，以及切断供给集合。第二角色制造逆向选择：提高 \\(p\\) 能拉进更好的车，也必须付更多；降低 \\(p\\) 更便宜，但平均质量更差。买方的支付意愿绑在 \\(\\mu(p)\\) 上，可以没有不动点，或不动点丢掉大量增益。这是 PBE 的混同（或半混同）在商品市场上的实现：单一公开价格无法让高 \\(\\theta\\) 付一份只对自己便宜的鉴定，切断点把好车留在场外。</p><p>这与<a href="/econ/core-equivalence">核</a>的对照：质量不可验证时，联盟无法用「带着好车走开」来阻塞，因为走开后买方仍看不见。核与竞争均衡一起建立在可描述商品上；柠檬是描述失败。第一定理并没有算错，是商品空间少了一维「可验证质量」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>若买方也有私型，双边逆向选择更狠。若有廉价交谈，不可验证时仍无用。竞争保险里的逆向选择是同一逻辑，Rothschild–Stiglitz 还加了菜单，那是筛选课。Akerlof 原文的「平均质量随价格」是局部市场故事，不是一般均衡存在性反例的全部；但足以推翻「有增益必有交易」。</p><p>强制公开、最低质量标准是另一条路：把 \\(\\theta\\) 的一部分变成可验证商品，切断集合被法规改写，不是被价格切断。本课不把标准写成最优机制。</p><p>后课默认：隐藏类型且不知情方只能看见价格时，逆向选择可以摧毁市场；要分离，需知情者先动（信号）或不知情者先出菜单（筛选）。</p><h3 id="保险是同一切断-担保是改树" tabindex="-1">保险是同一切断，担保是改树 <a class="header-anchor" href="#保险是同一切断-担保是改树" aria-label="Permalink to &quot;保险是同一切断，担保是改树&quot;">​</a></h3><p>保险里高风险更愿意在给定保费下投保，条件风险变差，保费再赶走低风险。这是柠檬的保单版；菜单与分离留给筛选课。线性教具：\\(\\theta\\sim U[0,1]\\)，卖方保留 \\(\\theta\\)，买方评价 \\((3/2)\\theta\\)。对称信息应全部成交。不对称且供给是「\\(\\theta\\le p\\)」时，\\(\\mathbb{E}[\\theta\\mid\\theta\\le p]=p/2\\)，买方最多出 \\(3p/4\\lt p\\)，唯一一致可以是 \\(p=0\\)。评价倍数够大时存在部分成交；要点是制度可以摧毁交易。</p><p>担保若可验证，等于把质量维补回商品空间，切断不再只靠价格。强制公开、最低质量标准同样改树，不是在原树上找另一个 \\(p\\)。买者的折价也不是限价簿价差：没有做市存货，只有平均质量定价。</p><p><span class="marginnote">Akerlof 原文是局部市场故事，不是一般均衡存在性的全部反例；但足以推翻「有增益必有交易」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>质量是隐藏类型；出售决策使市场上的条件质量变差。</li><li>价格同时做支付与切断，均衡可以空或不有效。</li><li>这是逆向选择，不是隐藏行动。</li><li>担保与信号是后课补上的商品或行动维。</li><li>出处：Akerlof, <em>QJE</em> 1970。</li></ul>',13))])}const b=r(E,[["render",c]]);export{k as __pageData,b as default};
